"""Regenerates src/data/images.gen.ts: intrinsic size of every JPG in public/images.
Run after adding or replacing photos:  python scripts/gen-images.py"""
import pathlib
from PIL import Image

root = pathlib.Path(__file__).resolve().parent.parent
out = {}
for p in sorted((root / "public/images").rglob("*.jpg")):
    key = p.relative_to(root / "public/images").as_posix()[:-4]
    with Image.open(p) as im:
        out[key] = (im.width, im.height)
body = ",\n".join(f'  "{k}": [{w}, {h}]' for k, (w, h) in out.items())
(root / "src/data/images.gen.ts").write_text(
    "// Generated by scripts/gen-images.py. Do not edit by hand.\n"
    "export const IMAGE_META = {\n" + body + ",\n} as const satisfies Record<string, readonly [number, number]>;\n",
    encoding="utf-8",
)
print(len(out), "images")
